,"sourceCheckedAt":"2026-11-17T21:34:47.615Z","visualReviewed":true}]$rows$::jsonb) as x("workId" bigint,locale text,"authorId" bigint,author text,"workOlid" text,"workTitle" text,title text,language text,"isbn13" text,"isbn10" text,publisher text,"openLibraryEditionId" text,"oldEdition" jsonb,"existingEdition" jsonb) loop
  if not exists(select 1 from public.works w join public.authors a on a.id=w.author_id where w.id=r."workId" and w.title=r."workTitle" and w.open_library_id=r."workOlid" and a.id=r."authorId" and a.name=r.author) then raise exception 'Work/author identity drift: %',r."workId";end if;
  select to_jsonb(e)-'preferred_for_catalog' into current_row from public.editions e where id=(r."oldEdition"->>'id')::bigint;
  if current_row is distinct from r."oldEdition"-'preferred_for_catalog' then raise exception 'Original edition drift: %',r."workId";end if;
  if exists(select 1 from public.editions where work_id<>r."workId" and ((r."isbn13" is not null and isbn_13=r."isbn13") or (r."openLibraryEditionId" is not null and open_library_edition_id=r."openLibraryEditionId"))) then raise exception 'Cross-Work identifier conflict: %',r."workId";end if;
  eid:=null;added:=false;
  if r."existingEdition" is not null then
   select id,to_jsonb(e)-'preferred_for_catalog' into eid,current_row from public.editions e where id=(r."existingEdition"->>'id')::bigint;
   if current_row is distinct from r."existingEdition"-'preferred_for_catalog' then raise exception 'Candidate edition drift: %',r."workId";end if;
  else
   select id into eid from public.editions where work_id=r."workId" and title=r.title and language=r.language and isbn_13 is not distinct from r."isbn13" and isbn_10 is not distinct from r."isbn10" and publisher is not distinct from r.publisher and open_library_edition_id is not distinct from r."openLibraryEditionId";
   if eid is null then
    insert into public.editions(work_id,title,language,isbn_13,isbn_10,publisher,open_library_edition_id) values(r."workId",r.title,r.language,r."isbn13",r."isbn10",r.publisher,r."openLibraryEditionId") returning id into eid;added:=true;
   end if;
  end if;
  if eid is null then raise exception 'Missing candidate edition';end if;
  if exists(select 1 from public.editions where work_id=r."workId" and (case when language='dut' then 'nld' else language end)=r.language and preferred_for_catalog and id<>eid) then raise exception 'Another preferred edition already exists: %',r."workId";end if;
  update public.editions set preferred_for_catalog=true where id=eid and not preferred_for_catalog;
  selected:=public.catalog_search_selection_v2(left(r.title,80),r.locale,p_alias_ids=>array[r."workId"]);
  if not exists(select 1 from jsonb_array_elements(selected->'candidates') c where c->>'workId'=r."workId"::text and c->>'editionId'=eid::text) then raise exception 'SQL selected another edition: %',r."workId";end if;
  insert into cover_recovery_receipt select r."workId",r.locale,eid,added,to_jsonb(e) from public.editions e where id=eid;
 end loop;
 if (select count(*) from cover_recovery_receipt)<>250 then raise exception 'Incomplete cover recovery';end if;
end $checked$;
select * from cover_recovery_receipt order by locale,work_id;
rollback;
